const translationResultElement = document.querySelector("#translation-result");
new MutationObserver(() => { try { const payload = JSON.parse(translationResultElement.textContent); const form = new FormData(translationForm); translationCandidate = {...payload, revision_path: String(form.get("source_revision_path") || ""), output_root: String(form.get("output_root") || "").replace(/[\\/]+$/, "")}; document.querySelector("#review-translation").disabled = false; } catch (_) { /* incomplete operation output */ } }).observe(translationResultElement, {childList: true, characterData: true, subtree: true});
function translationReviewRequest(extra = {}) { return {review_path: translationReview?.review_path || "", result_path: translationCandidate.result_path, revision_path: translationCandidate.revision_path, parent_translation_path: translationCandidate.candidate_path, ...extra}; }
function resizeTranslationTarget(input) { input.style.height = "auto"; input.style.height = `${Math.max(input.scrollHeight, 48)}px`; }
