document.querySelector("#save-translation-review").addEventListener("click", async () => { const targets = [...document.querySelectorAll("#translation-review-editor textarea")].map(item => ({unit_id: item.dataset.unitId, target_text: item.value})); try { renderTranslationReview(await queuePost("/api/v1/translation-reviews/save", translationReviewRequest({review_sha256: translationReview.review_sha256, targets}))); document.querySelector("#apply-translation-review").disabled = true; } catch (error) { document.querySelector("#translation-review-status").textContent = error.message; } });
document.querySelector("#preview-translation-review").addEventListener("click", async () => { try { const payload = await queuePost("/api/v1/translation-reviews/preview", translationReviewRequest()); document.querySelector("#translation-review-result").textContent = JSON.stringify(payload, null, 2); const summary = document.querySelector("#translation-review-summary"); const table = document.createElement("table"); table.className = "review-summary-table"; const rows = [["Validation", "Passed"], ["Publication", "None — preview only"], ["Units", payload.statistics.unit_count], ["Source tokens", payload.statistics.source_tokens], ["Target tokens", payload.statistics.target_tokens], ["Warnings", payload.warnings.length]]; const body = document.createElement("tbody"); for (const [label, value] of rows) { const row = document.createElement("tr"); const heading = document.createElement("th"); heading.scope = "row"; heading.textContent = label; const cell = document.createElement("td"); cell.textContent = String(value); row.append(heading, cell); body.append(row); } table.append(body); summary.replaceChildren(table); document.querySelector("#translation-review-status").textContent = "Preview passed: exact source lineage, complete target text, and immutable unit ownership validated. No translation was published."; document.querySelector("#apply-translation-review").disabled = false; } catch (error) { document.querySelector("#translation-review-status").textContent = error.message; } });
document.querySelector("#apply-translation-review").addEventListener("click", async () => { try { const root = translationCandidate.output_root; const payload = await queuePost("/api/v1/translation-reviews/apply", translationReviewRequest({translation_output_directory: `${root}/accepted-translations`, confirmed: document.querySelector("#translation-review-confirmed").checked})); appliedTranslation = payload.translation_path; document.querySelector("#translation-review-result").textContent = JSON.stringify(payload, null, 2); document.querySelector("#translation-review-status").textContent = "Verified manual translation applied."; document.querySelector("#export-translation-review").disabled = false; } catch (error) { document.querySelector("#translation-review-status").textContent = error.message; } });
document.querySelector("#export-translation-review").addEventListener("click", async () => { try { const root = translationCandidate.output_root; const formats = [...document.querySelectorAll('input[name="translation-format"]:checked')].map(item => item.value); const payload = await queuePost("/api/v1/translation-reviews/audit-export", translationReviewRequest({translation_path: appliedTranslation, audit_output_directory: `${root}/translation-audits`, export_output_directory: `${root}/translation-exports`, formats})); document.querySelector("#translation-review-result").textContent = JSON.stringify(payload, null, 2); document.querySelector("#translation-review-status").textContent = "Verified translation audited and exported."; } catch (error) { document.querySelector("#translation-review-status").textContent = error.message; } });
const dictionaryForm = document.querySelector("#dictionary-workflow");
let dictionaryProposal = null;
function renderDictionaryProposal(payload) { dictionaryProposal = payload; const editor = document.querySelector("#dictionary-editor"); editor.replaceChildren(); payload.candidates.forEach((candidate, index) => { const fieldset = document.createElement("fieldset"); fieldset.className = "dictionary-candidate"; const legend = document.createElement("legend"); legend.textContent = `${index + 1}. ${candidate.source} → ${candidate.target}`; const meta = document.createElement("p"); meta.textContent = `${candidate.occurrences} occurrence(s) across ${candidate.case_count} case(s)`; const select = document.createElement("select"); select.dataset.source = candidate.source; select.dataset.target = candidate.target; for (const status of ["pending", "approved", "rejected"]) { const option = document.createElement("option"); option.value = status; option.textContent = status; option.selected = candidate.status === status; select.append(option); } fieldset.append(legend, meta, select); candidate.evidence.forEach(example => { const details = document.createElement("details"); const summary = document.createElement("summary"); summary.textContent = `Example · ${example.job_id}`; const source = document.createElement("p"); source.textContent = `Before: ${example.source_context}`; const target = document.createElement("p"); target.textContent = `After: ${example.target_context}`; details.append(summary, source, target); fieldset.append(details); }); editor.append(fieldset); }); document.querySelector("#save-dictionary-decisions").disabled = false; document.querySelector("#publish-dictionary").disabled = payload.counts.pending !== 0; document.querySelector("#dictionary-status").textContent = `${payload.project_id}: ${payload.candidates.length} candidates; ${payload.counts.pending} pending, ${payload.counts.approved} approved, ${payload.counts.rejected} rejected.`; document.querySelector("#dictionary-result").textContent = JSON.stringify(payload, null, 2); }
dictionaryForm.addEventListener("submit", async event => { event.preventDefault(); const form = new FormData(dictionaryForm); const request = {canonical_directory: form.get("canonical_directory"), revision_directory: form.get("revision_directory"), output_root: form.get("output_root"), project_id: form.get("project_id"), minimum_occurrences: Number(form.get("minimum_occurrences")), previous_dictionary: form.get("previous_dictionary")}; try { renderDictionaryProposal(await queuePost("/api/v1/dictionaries/propose", request)); } catch (error) { document.querySelector("#dictionary-status").textContent = error.message; } });
document.querySelector("#save-dictionary-decisions").addEventListener("click", async () => { const decisions = [...document.querySelectorAll("#dictionary-editor select")].map(item => ({source: item.dataset.source, target: item.dataset.target, status: item.value})); try { renderDictionaryProposal(await queuePost("/api/v1/dictionaries/save", {proposal_path: dictionaryProposal.proposal_path, proposal_sha256: dictionaryProposal.proposal_sha256, decisions})); } catch (error) { document.querySelector("#dictionary-status").textContent = error.message; } });
document.querySelector("#publish-dictionary").addEventListener("click", async () => { const form = new FormData(dictionaryForm); try { const payload = await queuePost("/api/v1/dictionaries/publish", {proposal_path: dictionaryProposal.proposal_path, dictionary_id: document.querySelector("#dictionary-id").value, output_root: form.get("output_root"), confirmed: document.querySelector("#dictionary-publish-confirmed").checked}); document.querySelector("#dictionary-status").textContent = "Versioned project dictionary published."; document.querySelector("#dictionary-result").textContent = JSON.stringify(payload, null, 2); } catch (error) { document.querySelector("#dictionary-status").textContent = error.message; } });
const dictionaryEditor = document.querySelector("#dictionary-editor");
const dictionarySummary = document.querySelector("#dictionary-summary");
dictionaryForm.after(dictionarySummary);
const dictionaryViewControls = document.createElement("div");
dictionaryViewControls.className = "dictionary-view-controls";
dictionaryViewControls.innerHTML = '<label>Candidate filter<select id="dictionary-filter"><option value="all">Show all</option><option value="pending">Only pending</option><option value="rejected">Only rejected</option><option value="hide-approved">Hide approved</option></select></label><label>Occurrence display<select id="dictionary-occurrence-layout"><option value="list">List</option><option value="sequential">Previous / next</option></select></label>';
dictionaryEditor.before(dictionaryViewControls);
function refreshDictionaryCandidates() { if (!dictionaryProposal) return; const filter = document.querySelector("#dictionary-filter").value; const layout = document.querySelector("#dictionary-occurrence-layout").value; [...dictionaryEditor.querySelectorAll(".dictionary-candidate")].forEach((card, index) => { const candidate = dictionaryProposal.candidates[index]; card.hidden = filter === "pending" ? candidate.status !== "pending" : filter === "rejected" ? candidate.status !== "rejected" : filter === "hide-approved" ? candidate.status === "approved" : false; const evidence = [...card.querySelectorAll("details")]; let position = Number(card.dataset.evidencePosition || 0); position = Math.min(position, Math.max(0, evidence.length - 1)); card.dataset.evidencePosition = String(position); evidence.forEach((item, evidenceIndex) => { item.hidden = layout === "sequential" ? evidenceIndex !== position : evidenceIndex >= 5 && card.dataset.showAll !== "true"; item.open = !item.hidden; }); const navigation = card.querySelector(".dictionary-evidence-navigation"); if (navigation) { navigation.hidden = layout !== "sequential" || evidence.length < 2; navigation.querySelector("span").textContent = `${position + 1} / ${evidence.length}`; } const more = card.querySelector(".dictionary-show-more"); if (more) { more.hidden = layout !== "list" || evidence.length <= 5; more.textContent = card.dataset.showAll === "true" ? "Show fewer occurrences" : `Show ${evidence.length - 5} more occurrences`; } }); }
function enhanceDictionaryProposal() { if (!dictionaryProposal) return; const table = document.createElement("table"); table.className = "review-summary-table"; const rows = [["Candidates", dictionaryProposal.candidates.length], ["Approved", dictionaryProposal.counts.approved], ["Rejected", dictionaryProposal.counts.rejected], ["Pending", dictionaryProposal.counts.pending]]; const body = document.createElement("tbody"); for (const [label, value] of rows) { const row = document.createElement("tr"); const heading = document.createElement("th"); heading.scope = "row"; heading.textContent = label; const cell = document.createElement("td"); cell.textContent = String(value); row.append(heading, cell); body.append(row); } table.append(body); dictionarySummary.replaceChildren(table); [...dictionaryEditor.querySelectorAll(".dictionary-candidate")].forEach(card => { const evidence = card.querySelectorAll("details"); if (evidence.length > 5) { const more = document.createElement("button"); more.type = "button"; more.className = "dictionary-show-more"; more.addEventListener("click", () => { card.dataset.showAll = card.dataset.showAll === "true" ? "false" : "true"; refreshDictionaryCandidates(); }); card.append(more); } if (evidence.length > 1) { const navigation = document.createElement("div"); navigation.className = "actions dictionary-evidence-navigation"; const previous = document.createElement("button"); previous.type = "button"; previous.textContent = "Previous occurrence"; const position = document.createElement("span"); const next = document.createElement("button"); next.type = "button"; next.textContent = "Next occurrence"; previous.addEventListener("click", () => { card.dataset.evidencePosition = String(Math.max(0, Number(card.dataset.evidencePosition || 0) - 1)); refreshDictionaryCandidates(); }); next.addEventListener("click", () => { card.dataset.evidencePosition = String(Math.min(evidence.length - 1, Number(card.dataset.evidencePosition || 0) + 1)); refreshDictionaryCandidates(); }); navigation.append(previous, position, next); card.append(navigation); } }); refreshDictionaryCandidates(); }
document.querySelector("#dictionary-filter").addEventListener("change", refreshDictionaryCandidates);
document.querySelector("#dictionary-occurrence-layout").addEventListener("change", refreshDictionaryCandidates);
new MutationObserver(() => { if (dictionaryProposal && dictionaryEditor.children.length) enhanceDictionaryProposal(); }).observe(dictionaryEditor, {childList: true});
const dictionaryStatus = document.querySelector("#dictionary-status");
new MutationObserver(() => { const message = dictionaryStatus.textContent; const confirmation = document.querySelector("#dictionary-publish-confirmed"); const dictionaryId = document.querySelector("#dictionary-id"); confirmation.closest("label").classList.toggle("field-error", message.includes("confirmation is required")); confirmation.setAttribute("aria-invalid", String(message.includes("confirmation is required"))); dictionaryId.classList.toggle("field-error", message.includes("Dictionary ID is required")); dictionaryId.setAttribute("aria-invalid", String(message.includes("Dictionary ID is required"))); if (message === "Versioned project dictionary published.") dictionaryStatus.scrollIntoView({behavior: "smooth", block: "center"}); }).observe(dictionaryStatus, {childList: true, characterData: true, subtree: true});
function installDictionaryPicker(pathInputId, kind) { const pathInput = document.querySelector(pathInputId); const container = document.createElement("div"); container.className = "dictionary-picker"; const catalogLabel = document.createElement("label"); catalogLabel.textContent = "Dictionary catalog directory"; const catalogInput = document.createElement("input"); catalogInput.value = "dictionaries"; const refresh = document.createElement("button"); refresh.type = "button"; refresh.textContent = "Refresh dictionary list"; const selectLabel = document.createElement("label"); selectLabel.textContent = `Available ${kind} dictionaries`; const select = document.createElement("select"); const empty = document.createElement("option"); empty.value = ""; empty.textContent = "None / use direct path below"; select.append(empty); catalogLabel.append(catalogInput); selectLabel.append(select); container.append(catalogLabel, refresh, selectLabel); pathInput.before(container); refresh.addEventListener("click", async () => { try { const payload = await queuePost("/api/v1/dictionaries/catalog", {catalog_directory: catalogInput.value}); select.replaceChildren(empty.cloneNode(true)); payload.items.filter(item => item.kind === kind).forEach(item => { const option = document.createElement("option"); option.value = item.path; const direction = kind === "translation" ? ` · ${item.source_language}→${item.target_language}` : ` · ${item.language}`; option.textContent = `${item.project_id} · ${item.dictionary_id} · v${item.version}${direction}`; select.append(option); }); } catch (error) { dictionaryStatus.textContent = error.message; } }); select.addEventListener("change", () => { if (select.value) pathInput.value = select.value; }); }
installDictionaryPicker("#correction-dictionary", "correction");
installDictionaryPicker("#translation-dictionary", "translation");
document.querySelectorAll(".dictionary-picker").forEach(picker => { const localStatus = document.createElement("p"); localStatus.className = "field-hint"; localStatus.setAttribute("role", "status"); localStatus.textContent = "Dictionary list not loaded."; picker.append(localStatus); const select = picker.querySelector("select"); new MutationObserver(() => { const count = Math.max(0, select.options.length - 1); localStatus.textContent = count ? `${count} compatible dictionary option(s) loaded.` : "No compatible dictionaries found in this catalog."; }).observe(select, {childList: true}); new MutationObserver(() => { if (dictionaryStatus.textContent.includes("GUI_DICTIONARY")) localStatus.textContent = dictionaryStatus.textContent; }).observe(dictionaryStatus, {childList: true, characterData: true, subtree: true}); });
function installConfirmationHighlight(statusSelector, confirmationSelector) { const status = document.querySelector(statusSelector); const confirmation = document.querySelector(confirmationSelector); const update = () => { const invalid = /confirmation is required/i.test(status.textContent); confirmation.closest("label").classList.toggle("field-error", invalid); confirmation.setAttribute("aria-invalid", String(invalid)); }; new MutationObserver(update).observe(status, {childList: true, characterData: true, subtree: true}); confirmation.addEventListener("change", () => { if (confirmation.checked) { confirmation.closest("label").classList.remove("field-error"); confirmation.setAttribute("aria-invalid", "false"); } }); }
